                            try {
                    await new Promise((resolve, reject) => {
                        const timeout = setTimeout(() => {
                            ws.close();
                            reject(new Error('timeout'));
                        }, 10000);

                        const ws = new WebSocket('ws://127.0.0.1:8090/api/servers/b6a29131-da10-4d19-add5-cddbdcad7911/ws');

                        ws.onerror = () => {
                            clearTimeout(timeout);
                            ws.close();
                            reject(new Error('ws_error'));
                        };

                        // Wings closes a suspended server's socket with 4409 before auth,
                        // which still proves the websocket reached Wings
                        ws.onclose = (event) => {
                            if (event.code === 4409) {
                                clearTimeout(timeout);
                                resolve();
