                        ws.onopen = () => {
                            ws.send(JSON.stringify({ event: 'auth', args: ['eyJ0eXAiOiJKV1QiLCJhbGciOiJIUzI1NiIsImp0aSI6IjQ0YWE1NzFiMzc2MzMwMGZkNDE3NTY1YjQzZjEzNzMzMjdiMjA3NzIzY2RlOGJhNDRlMTFlNmEwYTRhNDk2ZjAifQ..kfNRcm5FFKx49__3fflO56mSW3zQRQb3hQhu4IF4z5c'] }));
