                        ws.onmessage = (event) => {
                            const data = JSON.parse(event.data);
                            if (data.event === 'auth success') {
                                clearTimeout(timeout);
                                ws.close();
                                resolve();
                            }
                        };
                    });
                    this.status = 'online';
                } catch (e) {
                    this.status = 'warning';
                }
                    }
    }"
    x-init="check()"
